import { setupScene, World } from './world.js';
import { CharacterController, PLAYER } from './physics.js';
import { Character } from './player.js';
import { sfx } from './sfx.js';
import { state, openWS, esc, toast } from '../api.js';

export class GameClient {
  constructor(root, gameId, onExit) {
    this.root = root;
    this.gameId = gameId;
    this.onExit = onExit;
    this.remotes = new Map(); // id -> {char, target, yaw, anim, username}
    this.hiddenCoins = new Map(); // partId -> respawnAt
    this.keys = {};
    this.camYaw = 0.6;
    this.camPitch = 0.42;
