    this.itId = null;
    this.lastTele = 0;
    this.pendingTouch = new Set();
    this.alive = true;

    this._buildDOM();
    const { renderer, scene, camera, resize } = setupScene(this.canvas);
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.resizeFn = resize;
    this.world = new World(scene);
    this._connect();
    this._bindInput();
  }

  _buildDOM() {
    this.root.innerHTML = `
      <canvas class="game-canvas"></canvas>
      <div class="hud" id="hud-top">
        <span id="hud-gamename">Connecting…</span>
        <button class="btn red" id="hud-leave">Leave</button>
        <div id="hud-lb"></div>
      </div>
      <div class="hud" id="hud-center"></div>
      <div class="hud" id="hud-chat">
        <div id="chat-log"></div>
        <input id="chat-input" type="text" maxlength="200" placeholder="Press / to chat" autocomplete="off">
      </div>
      <div class="hud" id="hud-controls-hint">WASD move · Space jump · drag to look · scroll zoom</div>
    `;
    this.canvas = this.root.querySelector('canvas');
    this.chatLog = this.root.querySelector('#chat-log');
    this.chatInput = this.root.querySelector('#chat-input');
    this.lbEl = this.root.querySelector('#hud-lb');
    this.centerEl = this.root.querySelector('#hud-center');
    this.root.querySelector('#hud-leave').onclick = () => this.exit();
  }

  _connect() {
    this.ws = openWS();
    this.ws.onopen = () => this.ws.send(JSON.stringify({ t: 'join', gameId: this.gameId }));
    this.ws.onclose = () => {
      if (this.alive) {
        toast('Disconnected from game', 'red');
        this.exit();
      }
    };
    this.ws.onmessage = (ev) => {
      let msg;
      try { msg = JSON.parse(ev.data); } catch (e) { return; }
      this._handle(msg);
    };
  }

  _send(msg) {
    if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(msg));
  }

  _handle(msg) {
    switch (msg.t) {
      case 'error':
        toast(msg.error, 'red');
        this.exit();
        break;
      case 'joined': {
        this.selfId = msg.selfId;
        this.config = msg.config;
        this.mode = msg.mode;
        this.world.timeOffset = msg.serverTime - Date.now();
        this.world.load(msg.world.parts);
        this.root.querySelector('#hud-gamename').textContent = msg.gameName;
        for (const tc of msg.takenCoins || []) this.hiddenCoins.set(tc.partId, tc.respawnAt);

        this.controller = new CharacterController(this.world, this.config);
        this.controller.onJump = () => sfx.jump();
        this.spawn = this.world.spawnPoint();
        this.controller.teleport(this.spawn);

        this.me = new Character(state.me.avatar, state.me.username, state.catalog);
        this.scene.add(this.me.group);

        for (const p of msg.players) this._addRemote(p);
        this._loop();
        break;
      }
      case 'pjoin':
        this._addRemote(msg.player);
        break;
      case 'pleave': {
        const r = this.remotes.get(msg.id);
        if (r) { r.char.dispose(); this.remotes.delete(msg.id); }
        break;
      }
      case 'p': {
        const r = this.remotes.get(msg.id);
        if (r) {
          r.target.set(msg.p[0], msg.p[1], msg.p[2]);
          r.yaw = msg.yaw;
          r.anim = msg.anim;
        }
        break;
      }
      case 'chat': {
        const div = document.createElement('div');
        if (msg.system) {
          div.className = 'sys';
          div.textContent = msg.text;
        } else {
          div.innerHTML = `<b>${esc(msg.username)}:</b> ${esc(msg.text)}`;
          const who = msg.id === this.selfId ? this.me : (this.remotes.get(msg.id) || {}).char;
          if (who) who.say(msg.text);
          sfx.chat();
        }
        this.chatLog.appendChild(div);
        while (this.chatLog.children.length > 30) this.chatLog.firstChild.remove();
        this.chatLog.scrollTop = this.chatLog.scrollHeight;
        break;
      }
      case 'coin': {
        this.hiddenCoins.set(msg.partId, msg.respawnAt);
        this.pendingTouch.delete(msg.partId);
        if (msg.by === this.selfId) sfx.coin();
        break;
      }
      case 'goalhit': {
        if (msg.by === this.selfId) {
          this.finished = true;
          sfx.goal();
          this._flash(`🏁 You reached the goal! +${msg.reward || 5} ◈`);
        } else {
          this._flash(`🏁 ${esc(msg.username)} reached the goal!`);
        }
        break;
      }
      case 'tag': {
        this.itId = msg.itId;
        sfx.tag();
        if (msg.itId === this.selfId) this._flash('⚡ You are ZAPPED! Tag someone!');
        this._applyItMarkers();
        break;
      }
      case 'lb': {
        this.itId = msg.itId;
        this._renderLB(msg.entries);
        this._applyItMarkers();
        break;
      }
      case 'pdied': {
        // remote death poof — small camera-facing flash at their spot
        const r = this.remotes.get(msg.id);
        if (r) r.char.group.position.copy(r.target);
        break;
      }
    }
  }

  _applyItMarkers() {
    if (this.me) this.me.setIt(this.itId === this.selfId);
    for (const [id, r] of this.remotes) r.char.setIt(this.itId === id);
  }

  _flash(html) {
    this.centerEl.innerHTML = html;
    clearTimeout(this._flashT);
    this._flashT = setTimeout(() => { this.centerEl.innerHTML = ''; }, 3000);
  }

  _renderLB(entries) {
    const statName = this.mode === 'obby' ? 'Stage' : this.mode === 'tag' ? 'Zaps' : this.mode === 'collect' ? 'Coins' : 'Score';
    let html = `<div class="lb-title">Players<span class="v" style="margin-left:auto">${statName}</span></div>`;
    for (const e of entries) {
      const v = this.mode === 'obby' ? e.stage : e.score;
      html += `<div class="lb-row${e.it ? ' it' : ''}">${e.it ? '⚡ ' : ''}${esc(e.username)}<span class="v">${v}</span></div>`;
    }
    this.lbEl.innerHTML = html;
  }

  _addRemote(p) {
    if (p.id === this.selfId || this.remotes.has(p.id)) return;
    const char = new Character(p.avatar, p.username, state.catalog);
    const pos = p.pos || [0, 5, 0];
    char.group.position.set(pos[0], pos[1], pos[2]);
    this.scene.add(char.group);
    this.remotes.set(p.id, {
      char,
      target: new THREE.Vector3(pos[0], pos[1], pos[2]),
      yaw: 0,
      anim: 'idle',
      username: p.username,
    });
    this._applyItMarkers();
  }

  _bindInput() {
    this._onKeyDown = (e) => {
      if (document.activeElement === this.chatInput) {
        if (e.key === 'Enter') {
          const text = this.chatInput.value.trim();
          if (text) this._send({ t: 'chat', text });
          this.chatInput.value = '';
          this.chatInput.blur();
        } else if (e.key === 'Escape') this.chatInput.blur();
        return;
      }
      if (e.key === '/' ) { e.preventDefault(); this.chatInput.focus(); return; }
      if (e.key === 'Enter') { this.chatInput.focus(); return; }
      this.keys[e.code] = true;
      if (e.code === 'Space') e.preventDefault();
      if (e.code === 'KeyR' && !this.dead) this._die(); // manual reset
    };
    this._onKeyUp = (e) => { this.keys[e.code] = false; };
    addEventListener('keydown', this._onKeyDown);
    addEventListener('keyup', this._onKeyUp);

    let dragging = false, lx = 0, ly = 0;
    this.canvas.addEventListener('mousedown', (e) => {
      dragging = true; lx = e.clientX; ly = e.clientY;
      sfx.unlock();
    });
    addEventListener('mouseup', () => { dragging = false; });
    addEventListener('mousemove', (e) => {
      if (!dragging) return;
      this.camYaw -= (e.clientX - lx) * 0.0065;
      this.camPitch = Math.min(1.45, Math.max(-0.5, this.camPitch + (e.clientY - ly) * 0.0065));
      lx = e.clientX; ly = e.clientY;
    });
    this.canvas.addEventListener('wheel', (e) => {
      this.camDist = Math.min(40, Math.max(4, this.camDist + e.deltaY * 0.012));
      e.preventDefault();
    }, { passive: false });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  }

  _die() {
    if (this.dead) return;
    this.dead = true;
    sfx.death();
    this._send({ t: 'died' });
    this._flash('💀 You died');
    setTimeout(() => {
      if (!this.alive) return;
      this.controller.teleport(this.spawn);
      this.dead = false;
    }, (this.config.respawnTime || 2) * 1000);
  }

  _handleTouches() {
    const now = Date.now();
    for (const part of this.controller.touching) {
      switch (part.type) {
        case 'kill':
          this._die();
          break;
        case 'coin':
          if (!this.hiddenCoins.has(part.id) && !this.pendingTouch.has(part.id)) {
            this.pendingTouch.add(part.id);
            this._send({ t: 'touch', partId: part.id });
          }
          break;
        case 'checkpoint': {
          const stage = part.stage || 1;
          if (stage > this.stage) {
            this.stage = stage;
            this.spawn = new THREE.Vector3(part.x, part.y + part.sy / 2 + 2.2, part.z);
            sfx.checkpoint();
            this._flash(`✅ Checkpoint ${stage}`);
            this._send({ t: 'stage', n: stage });
          }
          break;
        }
        case 'goal':
          if (!this.finished && !this.pendingTouch.has(part.id)) {
            this.pendingTouch.add(part.id);
            this._send({ t: 'touch', partId: part.id });
          }
          break;
        case 'bounce':
          if (this.controller.groundPart === part || this.controller.vel.y <= 0.5) {
            this.controller.vel.y = this.config.jumpPower * 1.65;
            this.controller.grounded = false;
            sfx.bounce();
          }
          break;
        case 'tele': {
          if (now - this.lastTele < 1200) break;
          const dest = this.world.telePartner(part);
          if (dest) {
            this.lastTele = now;
            this.controller.teleport(new THREE.Vector3(dest.x, dest.y + dest.sy / 2 + PLAYER.hh + 0.2, dest.z));
            sfx.tele();
          }
          break;
        }
      }
    }
  }

  _loop() {
    let last = performance.now();
    let netAcc = 0;
    const animate = (now) => {
      if (!this.alive) return;
      this.raf = requestAnimationFrame(animate);
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      this.resizeFn();

      // coin respawns
      const nowMs = Date.now();
      for (const [id, t] of this.hiddenCoins) if (t <= nowMs) this.hiddenCoins.delete(id);

      this.world.tick(dt, this.hiddenCoins);

      // local character
      const typing = document.activeElement === this.chatInput;
      const input = {
        moveX: (!typing && (this.keys.KeyD || this.keys.ArrowRight) ? 1 : 0) - (!typing && (this.keys.KeyA || this.keys.ArrowLeft) ? 1 : 0),
        moveZ: (!typing && (this.keys.KeyW || this.keys.ArrowUp) ? 1 : 0) - (!typing && (this.keys.KeyS || this.keys.ArrowDown) ? 1 : 0),
        jump: !typing && !!this.keys.Space,
        yaw: this.camYaw,
      };
      if (this.dead) { input.moveX = input.moveZ = 0; input.jump = false; }

      this.controller.step(dt, input);
      this._handleTouches();
      if (this.controller.pos.y < -50) this._die();

      // pose local avatar
      const moving = input.moveX !== 0 || input.moveZ !== 0;
      const anim = !this.controller.grounded && !this.controller.inWater ? 'jump' : moving ? 'walk' : 'idle';
      this.me.group.position.copy(this.controller.pos);
      this.me.group.position.y -= 0.30; // model center vs collider center
      if (moving) {
        const targetYaw = Math.atan2(this.controller.vel.x, this.controller.vel.z);
        let d = targetYaw - this.me.group.rotation.y;
        while (d > Math.PI) d -= Math.PI * 2;
        while (d < -Math.PI) d += Math.PI * 2;
        this.me.group.rotation.y += d * Math.min(1, dt * 14);
      }
      this.me.animate(dt, anim, this.controller.onSpeedPad ? 1.6 : 1);
      this.me.group.visible = !this.dead;

      // remote players: interpolate
      for (const r of this.remotes.values()) {
        r.char.group.position.lerp(r.target, Math.min(1, dt * 12));
        let d = (r.yaw || 0) - r.char.group.rotation.y;
        while (d > Math.PI) d -= Math.PI * 2;
        while (d < -Math.PI) d += Math.PI * 2;
        r.char.group.rotation.y += d * Math.min(1, dt * 10);
        r.char.animate(dt, r.anim || 'idle');
      }

      // camera orbit
      const look = this.controller.pos.clone();
      look.y += 1.2;
      const cp = new THREE.Vector3(
        look.x + Math.sin(this.camYaw) * Math.cos(this.camPitch) * this.camDist,
        look.y + Math.sin(this.camPitch) * this.camDist,
        look.z + Math.cos(this.camYaw) * Math.cos(this.camPitch) * this.camDist
      );
      this.camera.position.lerp(cp, Math.min(1, dt * 20));
      this.camera.lookAt(look);

      // network: send position ~15Hz
      netAcc += dt;
      if (netAcc > 0.066) {
        netAcc = 0;
        this._send({
          t: 'move',
          p: [+this.controller.pos.x.toFixed(2), +this.controller.pos.y.toFixed(2), +this.controller.pos.z.toFixed(2)],
          yaw: +this.me.group.rotation.y.toFixed(2),
          anim,
        });
      }

      this.renderer.render(this.scene, this.camera);
    };
    this.raf = requestAnimationFrame(animate);
  }

  exit() {
    if (!this.alive) return;
    this.alive = false;
    cancelAnimationFrame(this.raf);
    removeEventListener('keydown', this._onKeyDown);
    removeEventListener('keyup', this._onKeyUp);
    try { this.ws.close(); } catch (e) {}
    this.renderer.dispose();
    this.onExit();
  }
}
